const lockObligationsByIDs = `-- name: LockObligationsByIDs :many
SELECT id, public_id, organization_id, shipment_id, awb, expected_minor, currency, consignor_customer_id, origin_franchise_id, destination_franchise_id, status, custodian_type, custodian_id, collected_minor, remitted_minor, adjusted_minor, waived_minor, collected_at, reconciled_at, remitted_at, closed_at, cancel_reason, metadata, created_at, updated_at, version FROM cod_obligations
WHERE organization_id = $1 AND id = ANY($2::bigint[])
ORDER BY id
FOR UPDATE
`

type LockObligationsByIDsParams struct {
	OrganizationID int64
	Ids            []int64
}

// Locks a batch in a deterministic order, so two concurrent transfers over
// overlapping sets deadlock-free serialise rather than interleave.
func (q *Queries) LockObligationsByIDs(ctx context.Context, arg LockObligationsByIDsParams) ([]CodObligation, error) {
	rows, err := q.db.Query(ctx, lockObligationsByIDs, arg.OrganizationID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CodObligation{}
	for rows.Next() {
		var i CodObligation
		if err := rows.Scan(
			&i.ID,
			&i.PublicID,
			&i.OrganizationID,
			&i.ShipmentID,
			&i.Awb,
			&i.ExpectedMinor,
			&i.Currency,
			&i.ConsignorCustomerID,
			&i.OriginFranchiseID,
			&i.DestinationFranchiseID,
			&i.Status,
			&i.CustodianType,
			&i.CustodianID,
			&i.CollectedMinor,
			&i.RemittedMinor,
			&i.AdjustedMinor,
			&i.WaivedMinor,
			&i.CollectedAt,
			&i.ReconciledAt,
			&i.RemittedAt,
			&i.ClosedAt,
			&i.CancelReason,
			&i.Metadata,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

